# >>> STATIC
_static_logging_level() {
    cat <<-'ARGCEOF'
	on	enables logging at log level low if logging is currently not enabled
	off	disables ufw managed logging
	low	logs all blocked packets not matching the defined policy (with rate limiting), as well as packets matching logged rules
	medium	log level low, plus all allowed packets not matching the defined policy, all INVALID packets, and all new connections
	high	log level medium (without rate limiting), plus all packets with rate limiting
	full	log level high without rate limiting
ARGCEOF
}

_static_status_verbosity() {
    cat <<-'ARGCEOF'
	verbose	show verbose firewall status
	numbered	show firewall status as numbered list of RULES
ARGCEOF
}
