# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_ufw_app_profile() {
    _helper_ufw_app_names
    printf 'all\n'
}

_choice_ufw_rule() {
    local prev="" n=${#argc__positionals[@]}
    (( n > 1 )) && prev="${argc__positionals[n-2]}"
    case "$prev" in
        on) _helper_ufw_interfaces; return 0 ;;
        proto) _helper_ufw_protocols; return 0 ;;
        app) _helper_ufw_app_names; return 0 ;;
        from | to) printf 'any\n'; return 0 ;;
        port | comment) return 0 ;;
    esac
    if (( n == 1 )); then
        case "$argc__cmd_fn" in
            delete) _helper_ufw_actions ;;
            route) _helper_ufw_route_actions ;;
        esac
    fi
    _helper_ufw_keywords
    _helper_ufw_app_names
    _helper_ufw_services
}

_helper_ufw_actions() {
    cat <<-'EOF'
	allow	delete an allow rule
	deny	delete a deny rule
	reject	delete a reject rule
	limit	delete a limit rule
	EOF
}

_helper_ufw_app_names() {
    local file
    for file in /etc/ufw/applications.d/*; do
        [[ -f "$file" ]] || continue
        gawk -F'[][]' '/^\[.+\]$/ { print $2 }' "$file"
    done
}

_helper_ufw_interfaces() {
    local path
    for path in /sys/class/net/*; do
        [[ -e "$path" ]] || continue
        printf '%s\n' "${path##*/}"
    done
}

_helper_ufw_keywords() {
    cat <<-'EOF'
	in	apply to incoming traffic
	out	apply to outgoing traffic
	on	restrict the rule to an interface
	log	log all new connections matching the rule
	log-all	log all packets matching the rule
	proto	specify the protocol
	from	specify the source address
	to	specify the destination address
	port	specify the port
	app	specify an application profile
	comment	add a comment to the rule
	any	any address
	EOF
}

_helper_ufw_protocols() {
    cat <<-'EOF'
	tcp	transmission control protocol
	udp	user datagram protocol
	ah	IPsec authentication header
	esp	IPsec encapsulating security payload
	gre	generic routing encapsulation
	vrrp	virtual router redundancy protocol
	ipv6	IPv6 over IPv4 tunnel
	igmp	internet group management protocol
	EOF
}

_helper_ufw_route_actions() {
    cat <<-'EOF'
	delete	delete route RULE|NUM
	insert	insert route RULE at NUM
	prepend	prepend route RULE
	allow	allow route RULE
	deny	deny route RULE
	reject	reject route RULE
	limit	limit route RULE
	EOF
}

_helper_ufw_services() {
    [[ -r /etc/services ]] || return 0
    gawk '!/^#/ && NF >= 2 { print $1 }' /etc/services
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
